/**
 * Builds layout rows to divide the space for label, value and trend inside the ContentGrid
 *
 * @param hasLabel -
 * @param hasValue -
 * @param hasTrend -
 */
export function buildValueContentGridRows(
  hasLabel: boolean,
  hasValue: boolean,
  hasTrend: boolean,
): string {
  const labelFraction = hasLabel ? '1fr' : '0fr';
  const valueFraction = hasValue ? '2fr' : '0fr';
  const trendFraction = hasTrend ? '1fr' : '0fr';

  return `${labelFraction} ${valueFraction} ${trendFraction}`;
}
